const crypto = require('crypto');

const JWT_SECRET = $env.JWT_SECRET || '';

const b64url = (buf) => Buffer.from(buf).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');

const fromB64url = (s) => Buffer.from(s.replace(/-/g, '+').replace(/_/g, '/'), 'base64');

/** Authorization: Bearer <jwt> başlığını doğrular; geçerliyse claim'leri döndürür. */
function verifyToken(headers) {
  const m = /^Bearer\s+(.+)$/i.exec((headers && headers.authorization) || '');
  if (!m || !JWT_SECRET) return null;
  const parts = m[1].split('.');
  if (parts.length !== 3) return null;
  const expected = b64url(crypto.createHmac('sha256', JWT_SECRET).update(`${parts[0]}.${parts[1]}`).digest());
  if (expected.length !== parts[2].length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(parts[2]))) return null;
  try {
    const claims = JSON.parse(fromB64url(parts[1]).toString('utf8'));
    return claims.exp > Date.now() / 1000 ? claims : null;
  } catch {
    return null;
  }
}

/** Doğrulama hatası: IF düğümü ok=false görünce doğrudan yanıtlar. */
const fail = (status, error, extra = {}) => [{ json: { ok: false, status, body: { error, ...extra } } }];

/** SQL'e gidecek veri: UTF-16LE JSON -> base64 (dbo.fn_DecodePayload çözer). */
const toPayload = (obj) => Buffer.from(JSON.stringify(obj), 'utf16le').toString('base64');

const toId = (v) => {
  const n = Number(v);
  return Number.isInteger(n) && n > 0 ? n : null;
};

/** Token'ı doğrular, gövdede userId varsa token ile eşleştiğini kontrol eder. */
function requireUser(req) {
  const claims = verifyToken(req.headers);
  if (!claims) return { error: fail(401, 'Oturum geçersiz veya süresi dolmuş. Lütfen tekrar giriş yapın.') };
  const bodyUser = req.body && req.body.userId;
  if (bodyUser !== undefined && bodyUser !== null && Number(bodyUser) !== Number(claims.sub)) {
    return { error: fail(403, 'Bu işlem için yetkiniz yok.') };
  }
  return { userId: Number(claims.sub) };
}

/** Metni temizler: kontrol karakterleri, fazla boşluk ve satırlar. */
const cleanText = (s) =>
  String(s || '')
    .replace(/\r\n?/g, '\n')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const req = $input.first().json;
const auth = requireUser(req);
if (auth.error) return auth.error;
const body = req.body || {};
const action = String(body.action || '');
const p = body.params || {};
const optId = (v) => (v === undefined || v === null || v === '' ? null : toId(v));
const params = {};

switch (action) {
  case 'dashboard':
  case 'stats':
  case 'courses.list':
    break;
  case 'courses.create': {
    const name = cleanText(p.name).replace(/\n/g, ' ');
    if (name.length < 2 || name.length > 150) return fail(400, 'Ders adı 2-150 karakter olmalı.');
    params.name = name;
    params.description = cleanText(p.description).slice(0, 1000) || null;
    break;
  }
  case 'courses.delete':
    if (!(params.courseId = toId(p.courseId))) return fail(400, 'courseId geçersiz.');
    break;
  case 'notes.list':
    params.courseId = optId(p.courseId);
    params.limit = Math.min(Math.max(Number(p.limit) || 50, 1), 200);
    break;
  case 'notes.get':
    if (!(params.id = toId(p.noteId))) return fail(400, 'noteId geçersiz.');
    break;
  case 'results.get':
    if (!(params.id = toId(p.resultId))) return fail(400, 'resultId geçersiz.');
    break;
  case 'chat.history':
  case 'chat.clear':
    params.courseId = optId(p.courseId);
    params.limit = Math.min(Math.max(Number(p.limit) || 50, 1), 200);
    break;
  case 'cards.due':
    params.courseId = optId(p.courseId);
    params.limit = Math.min(Math.max(Number(p.limit) || 20, 1), 100);
    break;
  case 'cards.review': {
    // SM-2 notu: 0-5 (uygulamada Tekrar=1, Zor=3, İyi=4, Kolay=5)
    const grade = Number(p.grade);
    if (!(params.id = toId(p.cardId))) return fail(400, 'cardId geçersiz.');
    if (!Number.isInteger(grade) || grade < 0 || grade > 5) return fail(400, 'grade 0-5 arasında bir tam sayı olmalı.');
    params.grade = grade;
    break;
  }
  default:
    return fail(400, `Bilinmeyen action: "${action}"`);
}
return [{ json: { ok: true, action, payload: toPayload({ userId: auth.userId, action, params }) } }];

const action = $('Girdiyi doğrula').first().json.action;
const r = $input.first().json;
const status = Number(r.status) || 200;
if (status === 404) return [{ json: { status, body: { error: 'Kayıt bulunamadı.' } } }];
const isList = ['courses.list', 'notes.list', 'chat.history', 'cards.due'].includes(action);
let data = r.data ? JSON.parse(r.data) : isList ? [] : null;

if (action === 'chat.history' && data) {
  data.forEach((m) => { m.sources = m.sources || []; });
}
if (action === 'results.get' && data) {
  data.results = (data.results || []).map(({ a, b, c, d, ...q }) => ({ ...q, options: [a, b, c, d] }));
}
if (action === 'dashboard' && data) {
  data.recentNotes = data.recentNotes || [];
  data.recentResults = data.recentResults || [];
}
if (action === 'stats' && data) {
  data.courses = data.courses || [];
  data.weakTopics = data.weakTopics || [];
}
return [{ json: { status, body: { data } } }];

const err = $input.first().json.error;
console.log('[db-error]', typeof err === 'string' ? err : JSON.stringify(err));
return [{ json: { status: 500, body: { error: 'Veritabanı işlemi başarısız oldu. Lütfen daha sonra tekrar deneyin.' } } }];
